import java.util.*;import blockbranch.Blockbranch;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.CompoundTag;import net.minecraft.util.RandomSource;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.chunk.ChunkGenerator;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.pieces.*;import net.minecraft.world.level.levelgen.structure.structures.*;import net.minecraft.world.level.levelgen.structure.templatesystem.StructureTemplate;
/** Native room and resident graph with saved original compounds and an opt-in coherent manor. */
public final class ReimaginedMansionPiece extends StructurePiece {
 public static final StructurePieceType TYPE=Registry.register(BuiltInRegistries.STRUCTURE_PIECE,Blockbranch.id("reimagined_mansion_v1"),(StructurePieceType)ReimaginedMansionPiece::new);public static void initialize(){MansionReplacementTemplateProcessor.initialize();}
 private int wingDefinition,perimeterDefinition,replacement;private MansionRoofPlan roof;private BlockPos entrance;private Direction entranceFacing;private int[] wingSteps=new int[0],entryProfile=new int[0];private int[][] galleryProfiles=new int[0][];private final BoundingBox core;private final int floor;private final List<BlockPos> openings,passage;
 private ReimaginedMansionPiece(BoundingBox core,int floor,List<BlockPos> openings,List<BlockPos> passage){super(TYPE,0,bounds(core,floor));this.core=core;this.floor=floor;this.openings=List.copyOf(openings);this.passage=List.copyOf(passage);}
 private ReimaginedMansionPiece(StructurePieceSerializationContext c,CompoundTag t){super(TYPE,t);if(t.contains("MansionReplacement")&&!(t.get("MansionReplacement") instanceof net.minecraft.nbt.IntTag))throw new IllegalArgumentException("Invalid mansion replacement tag");replacement=t.getIntOr("MansionReplacement",0);if(replacement<0||replacement>1)throw new IllegalArgumentException("Unknown mansion replacement definition");int[] b=t.getIntArray("Core").orElseThrow(),a=t.getIntArray("Openings").orElseThrow();if(t.getIntOr("LayoutDefinition",0)!=1||b.length!=6||a.length%3!=0||a.length>96)throw new IllegalArgumentException("Invalid mansion layout");if(t.contains("MansionPerimeter")&&!(t.get("MansionPerimeter") instanceof net.minecraft.nbt.IntTag))throw new IllegalArgumentException("Invalid mansion perimeter tag");perimeterDefinition=t.getIntOr("MansionPerimeter",0);if(perimeterDefinition<0||perimeterDefinition>1)throw new IllegalArgumentException("Unknown mansion perimeter definition");wingDefinition=t.getIntOr("WingDefinition",0);if(wingDefinition<0||wingDefinition>1)throw new IllegalArgumentException("Unknown mansion wing definition");core=new BoundingBox(b[0],b[1],b[2],b[3],b[4],b[5]);floor=t.getIntOr("Floor",0);wingSteps=t.getIntArray("WingSteps").orElse(new int[0]).clone();if(wingDefinition==0&&t.contains("WingSteps")||wingDefinition==1&&(wingSteps.length!=4||java.util.Arrays.stream(wingSteps).anyMatch(v->v<1||v>10)))throw new IllegalArgumentException("Invalid mansion wing approaches");var list=new ArrayList<BlockPos>();for(int i=0;i<a.length;i+=3)list.add(new BlockPos(a[i],a[i+1],a[i+2]));openings=List.copyOf(list);int[] path=t.getIntArray("Passage").orElse(new int[0]);if(path.length!=0&&path.length!=6)throw new IllegalArgumentException("Invalid service passage");var ends=new ArrayList<BlockPos>();for(int i=0;i<path.length;i+=3)ends.add(new BlockPos(path[i],path[i+1],path[i+2]));passage=List.copyOf(ends);if(replacement==1){if(wingDefinition!=1||perimeterDefinition!=1||passage.size()!=2)throw new IllegalArgumentException("Incomplete replacement manor");int[] entry=t.getIntArray("MansionEntrance").orElseThrow(()->new IllegalArgumentException("Missing manor entrance"));if(entry.length!=5||entry[1]!=floor||Math.abs((long)entry[3])+Math.abs((long)entry[4])!=1)throw new IllegalArgumentException("Invalid manor entrance");entrance=new BlockPos(entry[0],entry[1],entry[2]);if(!core.isInside(entrance))throw new IllegalArgumentException("Manor entrance outside native bounds");entranceFacing=entry[3]<0?Direction.WEST:entry[3]>0?Direction.EAST:entry[4]<0?Direction.NORTH:Direction.SOUTH;if(!(t.get("MansionEntryProfile") instanceof net.minecraft.nbt.IntArrayTag))throw new IllegalArgumentException("Invalid manor entry profile tag");entryProfile=MansionReplacement.validateEntryProfile(t.getIntArray("MansionEntryProfile").orElseThrow());if(!(t.get("MansionGalleryApproaches") instanceof net.minecraft.nbt.IntArrayTag))throw new IllegalArgumentException("Invalid gallery approach tag");galleryProfiles=MansionReplacement.readGalleryProfiles(t.getIntArray("MansionGalleryApproaches").orElseThrow());roof=MansionRoofPlan.load(t.getCompound("MansionRoofPlan").orElseThrow(()->new IllegalArgumentException("Missing mansion roof plan")),bounds(core,floor,1));}else if(t.contains("MansionRoofPlan")||t.contains("MansionEntryProfile")||t.contains("MansionEntrance")||t.contains("MansionGalleryApproaches"))throw new IllegalArgumentException("Roof plan without mansion replacement");if(!getBoundingBox().equals(bounds(core,floor,replacement)))throw new IllegalArgumentException("Mansion bounds differ");for(var end:passage)if(!boundingBox.isInside(end)||end.getY()<floor||end.getY()>floor+5)throw new IllegalArgumentException("Service endpoint outside admitted bounds");for(var end:openings)if(!boundingBox.isInside(end))throw new IllegalArgumentException("Mansion opening outside admitted bounds");}
 private static BoundingBox bounds(BoundingBox c,int y){return new BoundingBox(c.minX()-21,y-12,c.minZ()-15,c.maxX()+21,Math.max(c.maxY(),y+18),c.maxZ()+15);}
 private static BoundingBox bounds(BoundingBox c,int y,int replacement){if(replacement==0)return bounds(c,y);return new BoundingBox(c.minX()-21,y-12,c.minZ()-15,c.maxX()+21,Math.max(c.maxY()+6,y+19),c.maxZ()+15);}
 public static Optional<Structure.GenerationStub> generate(Structure.GenerationContext c,RealisticGenerator g){return g.reimagined(c.randomState()).forStart(4,c.chunkPos().x(),c.chunkPos().z()).flatMap(p->{var rotation=Rotation.getRandom(c.random());var pieces=new ArrayList<WoodlandMansionPieces.WoodlandMansionPiece>();WoodlandMansionPieces.generateMansion(c.structureTemplateManager(),p.center(),rotation,pieces,c.random());var original=BoundingBox.encapsulatingBoxes(pieces.stream().map(StructurePiece::getBoundingBox).toList()).orElseThrow();int dx=p.x()-(original.minX()+original.maxX())/2,dz=p.z()-(original.minZ()+original.maxZ())/2;pieces.forEach(v->v.move(dx,0,dz));var core=BoundingBox.encapsulatingBoxes(pieces.stream().map(StructurePiece::getBoundingBox).toList()).orElseThrow();var doors=new ArrayList<BlockPos>();
  // Ground-floor native window panels are the only cut-throughs; room markers/containers are protected at placement.
  for(var piece:pieces){String template=((blockbranch.mixin.cubic.ReimaginedTemplateName)piece).blockbranch$reimaginedTemplate();if(!template.endsWith("wall_window")||piece.templatePosition().getY()>p.y()+1)continue;for(int x=0;x<=1;x++)for(int z=3;z<=4;z++)for(int y=1;y<=3;y++){var local=StructureTemplate.transform(new BlockPos(x,y,z),piece.placeSettings().getMirror(),piece.placeSettings().getRotation(),piece.placeSettings().getRotationPivot());doors.add(piece.templatePosition().offset(local));}if(doors.size()>=24)break;}
  var entrance=pieces.stream().filter(v->((blockbranch.mixin.cubic.ReimaginedTemplateName)v).blockbranch$reimaginedTemplate().endsWith("entrance")).findFirst().orElseThrow();var inside=entrance.templatePosition().offset(StructureTemplate.transform(new BlockPos(12,2,13),entrance.placeSettings().getMirror(),entrance.placeSettings().getRotation(),entrance.placeSettings().getRotationPivot()));var passage=List.of(new BlockPos(core.maxX()+16,p.y(),core.maxZ()-11),inside);var layout=new ReimaginedMansionPiece(core,p.y(),doors,passage);layout.wingDefinition=g.mansionWingDefinition();layout.perimeterDefinition=g.reimaginedDefinition()>=5?1:0;layout.replacement=g.mansionReplacementDefinition();if(layout.replacement==1){layout.boundingBox=bounds(core,p.y(),1);layout.roof=MansionRoofPlan.capture(pieces,layout.boundingBox);var settings=entrance.placeSettings();/* The native outer porch spans z5..9; centre z7 aligns the z6..8 doorway, independently of the service hatch. */var porch=StructureTemplate.transform(new BlockPos(20,0,7),settings.getMirror(),settings.getRotation(),settings.getRotationPivot());var ahead=StructureTemplate.transform(new BlockPos(21,0,7),settings.getMirror(),settings.getRotation(),settings.getRotationPivot());layout.entrance=entrance.templatePosition().offset(porch);int ex=ahead.getX()-porch.getX(),ez=ahead.getZ()-porch.getZ();layout.entranceFacing=ex<0?Direction.WEST:ex>0?Direction.EAST:ez<0?Direction.NORTH:Direction.SOUTH;}var b=layout.getBoundingBox();if(b.minX()<p.x()-96||b.maxX()>p.x()+96||b.minZ()<p.z()-96||b.maxZ()>p.z()+96)return Optional.empty();if(layout.wingDefinition==1){var terrain=g.hutPlanningTerrain(c.randomState()).drainage();layout.wingSteps=new int[]{approach(terrain,core.minX()-21,core.minZ()+8,p.y()),approach(terrain,core.minX()-11,core.minZ()+8,p.y()),approach(terrain,core.maxX()+11,core.maxZ()-28,p.y()),approach(terrain,core.maxX()+21,core.maxZ()-28,p.y())};}if(layout.replacement==1){var terrain=g.hutPlanningTerrain(c.randomState()).drainage();layout.entryProfile=MansionReplacement.entryProfile(p.y(),layout.entrance,layout.entranceFacing,(x,z)->terrain.sample(x,z).height());layout.galleryProfiles=MansionReplacement.galleryProfiles(core,p.y(),(x,z)->terrain.sample(x,z).height());}if(layout.replacement==1)for(var piece:pieces)((MansionReplacementTemplateAccess)piece).blockbranch$configureMansionReplacement(1,p.y());return Optional.of(new Structure.GenerationStub(p.center(),builder->{builder.addPiece(new ReimaginedTreeClearPiece(layout.getBoundingBox(),c.seed(),g.borealCrownDefinition(),g.vegetationFlags()));pieces.forEach(builder::addPiece);builder.addPiece(layout);}));});}
 // Blueprint lengths use only immutable base terrain and are saved before clipped placement.
 // Compare the cell beyond the final stair, so its next step reaches supported ground.
 private static int approach(DrainageNetwork terrain,int x,int z,int floor){for(int i=0;i<10;i++)if(terrain.sample(x,z+6+i).height()>=floor-i-1)return i+1;throw new IllegalStateException("Mansion approach exceeds admitted relief");}
 @Override protected void addAdditionalSaveData(StructurePieceSerializationContext c,CompoundTag t){t.putInt("LayoutDefinition",1);if(perimeterDefinition>0)t.putInt("MansionPerimeter",perimeterDefinition);if(wingDefinition>0){t.putInt("WingDefinition",wingDefinition);t.putIntArray("WingSteps",wingSteps.clone());}if(replacement==1){t.putInt("MansionReplacement",1);t.put("MansionRoofPlan",roof.save());t.putIntArray("MansionEntryProfile",entryProfile.clone());t.putIntArray("MansionGalleryApproaches",MansionReplacement.saveGalleryProfiles(galleryProfiles));t.putIntArray("MansionEntrance",new int[]{entrance.getX(),entrance.getY(),entrance.getZ(),entranceFacing.getStepX(),entranceFacing.getStepZ()});}t.putIntArray("Core",new int[]{core.minX(),core.minY(),core.minZ(),core.maxX(),core.maxY(),core.maxZ()});t.putInt("Floor",floor);t.putIntArray("Passage",passage.stream().flatMapToInt(p->java.util.stream.IntStream.of(p.getX(),p.getY(),p.getZ())).toArray());t.putIntArray("Openings",openings.stream().flatMapToInt(p->java.util.stream.IntStream.of(p.getX(),p.getY(),p.getZ())).toArray());}
 @Override public void postProcess(WorldGenLevel level,StructureManager structures,ChunkGenerator generator,RandomSource random,BoundingBox clip,ChunkPos chunk,BlockPos pivot){var w=new Writer(level,clip);if(replacement==1){MansionReplacement.generate(w::state,core,wingSteps,entrance,entranceFacing,entryProfile,galleryProfiles);servicePassage(w);for(var p:openings)if(clip.isInside(p)&&level.getBlockEntity(p)==null){var state=level.getBlockState(p);if(!state.is(Blocks.CHEST)&&!state.is(Blocks.TRAPPED_CHEST)&&!state.is(Blocks.SPAWNER))level.setBlock(p,Blocks.AIR.defaultBlockState(),2);}roof.place(clip,(position,state)->{if(!boundingBox.isInside(position))throw new IllegalStateException("Manor roof outside saved bounds");level.setBlock(position,state,2);});return;}int x0=core.minX()-10,x1=core.maxX()+10,z0=core.minZ()-10,z1=core.maxZ()+10;
  // Four continuous walks frame the occupied native room graph; gates on every side keep its original entrance reachable.
  w.box(x0,-10,z0,x1,-1,z0+3,Blocks.COBBLESTONE);w.box(x0,-10,z1-3,x1,-1,z1,Blocks.COBBLESTONE);w.box(x0,-10,z0,x0+3,-1,z1,Blocks.COBBLESTONE);w.box(x1-3,-10,z0,x1,-1,z1,Blocks.COBBLESTONE);
  for(int z:new int[]{z0,z1}){w.box(x0,0,z,x1,8,z,Blocks.STONE_BRICKS);w.box(x0,8,z-1,x1,8,z+1,Blocks.DARK_OAK_PLANKS);for(int x=x0;x<=x1;x+=3)w.box(x,9,z,x,10,z,Blocks.COBBLESTONE_WALL);int mid=(x0+x1)/2;w.box(mid-3,0,z,mid+3,5,z,Blocks.AIR);}
  for(int x:new int[]{x0,x1}){w.box(x,0,z0,x,8,z1,Blocks.STONE_BRICKS);w.box(x-1,8,z0,x+1,8,z1,Blocks.DARK_OAK_PLANKS);for(int z=z0;z<=z1;z+=3)w.box(x,9,z,x,10,z,Blocks.COBBLESTONE_WALL);int mid=(z0+z1)/2;w.box(x,0,mid-3,x,5,mid+3,Blocks.AIR);}
  for(int x:new int[]{x0,x1})for(int z:new int[]{z0,z1})tower(w,x-3,z-3);
  if(perimeterDefinition==1)MansionPerimeterStonework.apply(w::state,x0,x1,z0,z1);
  wing(w,core.minX()-20,core.minZ()+8,8,22,true);wing(w,core.maxX()+12,core.maxZ()-28,8,20,false);
  // Four broad stairs make the high circuit a usable alternate route, not a sealed decoration.
  for(int i=0;i<9;i++){w.box(x0+3,-10,z0+4+i,x0+5,i-1,z0+4+i,Blocks.COBBLESTONE);w.box(x0+3,i,z0+4+i,x0+5,i+3,z0+4+i,Blocks.AIR);w.box(x1-5,-10,z1-4-i,x1-3,i-1,z1-4-i,Blocks.COBBLESTONE);w.box(x1-5,i,z1-4-i,x1-3,i+3,z1-4-i,Blocks.AIR);}
  w.box(x0,8,z0+13,x0+5,8,z0+15,Blocks.DARK_OAK_PLANKS);w.box(x1-5,8,z1-15,x1,8,z1-13,Blocks.DARK_OAK_PLANKS);
  servicePassage(w);
  for(var p:openings)if(clip.isInside(p)&&level.getBlockEntity(p)==null){var state=level.getBlockState(p);if(!state.is(Blocks.CHEST)&&!state.is(Blocks.TRAPPED_CHEST)&&!state.is(Blocks.SPAWNER))level.setBlock(p,Blocks.AIR.defaultBlockState(),2);}
 }
 private void servicePassage(Writer w){if(passage.isEmpty())return;var a=passage.get(0);var b=passage.get(1);int lo=Math.min(a.getX(),b.getX()),hi=Math.max(a.getX(),b.getX());w.box(lo-1,-5,a.getZ()-2,hi+1,-1,a.getZ()+2,Blocks.STONE_BRICKS);w.box(lo,-4,a.getZ()-1,hi,-2,a.getZ()+1,Blocks.AIR);lo=Math.min(a.getZ(),b.getZ());hi=Math.max(a.getZ(),b.getZ());w.box(b.getX()-2,-5,lo-1,b.getX()+2,-1,hi+1,Blocks.STONE_BRICKS);w.box(b.getX()-1,-4,lo,b.getX()+1,-2,hi,Blocks.AIR);w.box(Math.min(a.getX(),b.getX()),-4,a.getZ()-1,Math.max(a.getX(),b.getX()),-2,a.getZ()+1,Blocks.AIR);
  for(var end:passage){int top=end.getY()-floor-1;for(int y=-4;y<top;y++){w.raw(end.getX()+1,y,end.getZ(),Blocks.STONE_BRICKS.defaultBlockState());w.raw(end.getX(),y,end.getZ(),Blocks.LADDER.defaultBlockState().setValue(LadderBlock.FACING,Direction.WEST));}w.raw(end.getX(),top,end.getZ(),Blocks.OAK_TRAPDOOR.defaultBlockState().setValue(TrapDoorBlock.HALF,net.minecraft.world.level.block.state.properties.Half.TOP).setValue(TrapDoorBlock.FACING,Direction.WEST));w.raw(end.getX(),top+1,end.getZ(),Blocks.AIR.defaultBlockState());w.raw(end.getX(),top+2,end.getZ(),Blocks.AIR.defaultBlockState());}
 }
 private void tower(Writer w,int x,int z){w.room(x,0,z,x+6,15,z+6,Blocks.STONE_BRICKS);w.box(x,-12,z,x+6,-1,z+6,Blocks.COBBLESTONE);w.box(x+2,0,z,x+4,3,z,Blocks.AIR);w.box(x+2,0,z+6,x+4,3,z+6,Blocks.AIR);w.box(x,9,z+2,x,12,z+4,Blocks.AIR);w.box(x+6,9,z+2,x+6,12,z+4,Blocks.AIR);w.box(x+2,9,z,x+4,12,z,Blocks.AIR);w.box(x+2,9,z+6,x+4,12,z+6,Blocks.AIR);w.box(x+1,8,z+1,x+5,8,z+5,Blocks.DARK_OAK_PLANKS);w.box(x+1,14,z+1,x+5,14,z+5,Blocks.DARK_OAK_PLANKS);for(int y=1;y<=14;y++)w.state(x+1,y,z+1,Blocks.LADDER.defaultBlockState().setValue(LadderBlock.FACING,Direction.SOUTH));for(int[] p:new int[][]{{0,0},{6,0},{0,6},{6,6}})w.box(x+p[0],15,z+p[1],x+p[0],17,z+p[1],Blocks.CHISELED_STONE_BRICKS);}
 private void wing(Writer w,int x,int z,int width,int length,boolean workshop){w.room(x,0,z,x+width,6,z+length,Blocks.DARK_OAK_PLANKS);w.box(x,-12,z,x+width,-1,z+length,Blocks.COBBLESTONE);for(int a:new int[]{x,x+width})for(int b:new int[]{z,z+length})w.box(a,0,b,a,7,b,Blocks.DARK_OAK_LOG);w.box(x,1,z+3,x,3,z+5,Blocks.AIR);w.box(x+width,1,z+3,x+width,3,z+5,Blocks.AIR);for(int i=0;i<=width/2;i++)w.box(x+i,7+i,z-1,x+width-i,7+i,z+length+1,Blocks.DARK_OAK_PLANKS);for(int a=z+8;a<z+length-2;a+=5){w.box(x+2,0,a,x+3,0,a,workshop?Blocks.CRAFTING_TABLE:Blocks.DARK_OAK_PLANKS);w.block(x+2,1,a,workshop?Blocks.ANVIL:Blocks.CARPET.pick(net.minecraft.world.item.DyeColor.RED));w.block(x+width-2,0,a,workshop?Blocks.FURNACE:Blocks.BOOKSHELF);}if(wingDefinition==1)MansionWingFacades.apply(w::state,x,z,width,length,workshop,wingSteps[workshop?0:2],wingSteps[workshop?1:3]); }
 private final class Writer{final WorldGenLevel level;final BoundingBox clip;Writer(WorldGenLevel l,BoundingBox c){level=l;clip=c;}void block(int x,int y,int z,Block b){state(x,y,z,b.defaultBlockState());}void state(int x,int y,int z,net.minecraft.world.level.block.state.BlockState s){var p=new BlockPos(x,floor+y,z);if(clip.isInside(p)&&!core.isInside(p))level.setBlock(p,s,2);}void raw(int x,int y,int z,net.minecraft.world.level.block.state.BlockState s){var p=new BlockPos(x,floor+y,z);if(clip.isInside(p)&&level.getBlockEntity(p)==null)level.setBlock(p,s,2);}void box(int x,int y,int z,int mx,int my,int mz,Block b){for(int xx=x;xx<=mx;xx++)for(int zz=z;zz<=mz;zz++)for(int yy=y;yy<=my;yy++)block(xx,yy,zz,b);}void room(int x,int y,int z,int mx,int h,int mz,Block b){box(x,y-1,z,mx,y+h,mz,b);box(x+1,y,z+1,mx-1,y+h-1,mz-1,Blocks.AIR);}}
}
